definition.script:
import groovy.json.JsonSlurper;

def targetStack
def infrastructureGitHash

pipeline {
    agent any

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Validate Selection') {
            steps {
                script {
                    if (!params.ROTATE_STACK_SECRETS && !params.ROTATE_LOGGING_API_KEY && !params.ROTATE_MCP_SERVICE_TOKEN) {
                        error("None of ROTATE_STACK_SECRETS, ROTATE_LOGGING_API_KEY and ROTATE_MCP_SERVICE_TOKEN is true, so this run would mint nothing and redeploy the gateway for no reason. Set at least one.")
                    }
                }
            }
        }

        stage('Retrieve Stack') {
            steps {
                script {
                    targetStack = sh(script: """
                    bash -c '
                    set +x

                    if [ ! -d "$SOURCE_SCRIPTS_FOLDER" ]; then
                        echo "Error: Source folder does not exist: $SOURCE_SCRIPTS_FOLDER"
                        exit 1
                    fi

                    for script_file in "$SOURCE_SCRIPTS_FOLDER"*.sh; do
                        chmod +x "\$script_file"
                        if [ -f "\$script_file" ] && [ -x "\$script_file" ]; then
                            . "\$script_file"
                        fi
                    done

                    get_stack \"${TARGET_STACK}\"
                    '
                    """, returnStdout: true).trim()

                    println "TARGET_STACK: $targetStack"
                }
            }
        }

        stage('Resolve Infrastructure Git Hash') {
            steps {
                script {
                    if (params.INFRASTRUCTURE_GIT_HASH?.trim()) {
                        infrastructureGitHash = params.INFRASTRUCTURE_GIT_HASH.trim()
                        echo "Using provided INFRASTRUCTURE_GIT_HASH: ${infrastructureGitHash}"
                    } else {
                        def result = build job: 'Retrieve Build Spec'
                        copyArtifacts filter: 'build-spec.json', projectName: 'Retrieve Build Spec', selector: specific("" + result.number)
                        def buildSpec = new JsonSlurper().parse(new File("${env.WORKSPACE}/build-spec.json"))
                        infrastructureGitHash = buildSpec.infrastructure_git_hash
                        echo "Resolved INFRASTRUCTURE_GIT_HASH from release control: ${infrastructureGitHash}"
                    }
                }
            }
        }

        stage('Rotate and Redeploy') {
            steps {
                script {
                    // The gateway carries a secret from every set, so it is in every selection.
                    def rotateStack = params.ROTATE_STACK_SECRETS
                    def rotateLogging = params.ROTATE_LOGGING_API_KEY
                    def rotateMcp = params.ROTATE_MCP_SERVICE_TOKEN
                    def renderMcp = rotateMcp || rotateLogging

                    echo "Rotating on stack ${targetStack}: stack secrets=${rotateStack}, logging api key=${rotateLogging}, mcp service token=${rotateMcp}"

                    lock("stack-${targetStack}") {
                        build job: 'Render PIC-SURE Configuration', parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructureGitHash],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPERATIONS', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_QUERY', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'RENDER_MCP', value: renderMcp],
                            [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: false],
                            [$class: 'BooleanParameterValue', name: 'RENDER_VISUALIZATION', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'RENDER_LOGGING', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'RENDER_DICTIONARY', value: false],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_STACK_SECRETS', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_LOGGING_API_KEY', value: rotateLogging],
                            [$class: 'BooleanParameterValue', name: 'ROTATE_MCP_SERVICE_TOKEN', value: rotateMcp]
                        ]

                        def stackDeploy = build job: 'PIC-SURE Wildfly Stack Deploy', propagate: false, parameters: [
                            [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                            [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: true],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_OPERATIONS', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_QUERY', value: rotateStack],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_MCP', value: renderMcp],
                            [$class: 'BooleanParameterValue', name: 'DEPLOY_VISUALIZATION', value: rotateLogging]
                        ]
                        def stackDeployResult = stackDeploy.result
                        def stackDeployFailed = stackDeployResult != 'SUCCESS'

                        if (stackDeployFailed && rotateLogging) {
                            echo "PIC-SURE Wildfly Stack Deploy finished ${stackDeployResult}. Deploying pic-sure-logging on the new LOGGING_API_KEY anyway, so the services that did come up keep auditing; any of them that did not stays on the old key until it is redeployed. This run fails once the logging deploy is done."
                        }

                        if (rotateLogging) {
                            build job: 'PIC-SURE Logging Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack]
                            ]

                            echo "LOGGING_API_KEY was rotated. configs/pic-sure-frontend/${targetStack}/bdc.env still holds the old key: update it and redeploy the frontend, or this stack's frontend audit events are dropped."
                        }

                        if (stackDeployFailed && rotateMcp) {
                            echo "MCP_SERVICE_TOKEN was rotated, but the render that clears MCP_SERVICE_TOKEN_PREVIOUS is skipped after a failed deploy, so the gateway on stack ${targetStack} still accepts the previous token until it is next rendered and redeployed. Redeploy pic-sure-mcp with PIC-SURE MCP Build and Deploy before any new MCP_SERVICE_TOKEN rotation: until then the running container may still present the older token, and a second rotation would drop it."
                        }

                        if (stackDeployFailed) {
                            error("PIC-SURE Wildfly Stack Deploy finished ${stackDeployResult} on stack ${targetStack}. Its console names the service that failed. Redeploy that service once the cause is fixed. For pic-sure-mcp that is PIC-SURE MCP Build and Deploy, which renders mcp.env from the values this run wrote. Run it before any new MCP_SERVICE_TOKEN rotation: until then the running container may still present the older token, and a second rotation would drop it.")
                        }

                        if (rotateMcp) {
                            build job: 'Render PIC-SURE Configuration', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructureGitHash],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                                [$class: 'BooleanParameterValue', name: 'RENDER_GATEWAY', value: true],
                                [$class: 'BooleanParameterValue', name: 'RENDER_OPERATIONS', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_QUERY', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_MCP', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_VISUALIZATION', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_LOGGING', value: false],
                                [$class: 'BooleanParameterValue', name: 'RENDER_DICTIONARY', value: false],
                                [$class: 'BooleanParameterValue', name: 'ROTATE_STACK_SECRETS', value: false],
                                [$class: 'BooleanParameterValue', name: 'ROTATE_LOGGING_API_KEY', value: false],
                                [$class: 'BooleanParameterValue', name: 'ROTATE_MCP_SERVICE_TOKEN', value: false]
                            ]

                            build job: 'PIC-SURE Wildfly Stack Deploy', parameters: [
                                [$class: 'StringParameterValue', name: 'S3_BUCKET_NAME', value: params.S3_BUCKET_NAME],
                                [$class: 'StringParameterValue', name: 'TARGET_STACK', value: targetStack],
                                [$class: 'BooleanParameterValue', name: 'DEPLOY_GATEWAY', value: true]
                            ]

                            echo "MCP_SERVICE_TOKEN was rotated and MCP_SERVICE_TOKEN_PREVIOUS is cleared: the gateway on stack ${targetStack} now accepts only the new token."
                        }
                    }
                }
            }
        }
    }
}
